contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 id, address to, address spender) public payable {
        require(to != address(0), "recipient must be non-zero");

        // Set up an approval on a token we will attempt to transfer.
        // The test contract is the caller (msg.sender) and, in the state we set up,
        // the owner of token `id` because we mint it to ourselves.
        c.mint(address(this), id);
        c.approve(spender, id);

        address approvedBefore = c.getApproved(id);

        // Decide the transfer: it may revert when the sender is not authorized.
        bool reverted;
        try c.transferFrom(address(this), to, id) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: the approval mapping for `id` is either reset to the zero
        // address (on a successful transfer) or left exactly as it was (on a revert).
        assert(reverted ? c.getApproved(id) == approvedBefore : c.getApproved(id) == address(0));
    }

    receive() external payable {}
}

